import { getMetaContent } from "helpers/meta_helpers"

// Offline HTML and Turbo's history snapshots must not outlive a language change.
// The tracked locale meta tag reloads permanent UI when the language changes.
document.addEventListener("turbo:load", () => {
  const locale = getMetaContent("locale")
  if (!locale) return

  try {
    const previousLocale = localStorage.getItem("fizzy-locale") || "en"
    if (previousLocale !== locale) {
      Turbo.cache.clear()
      Turbo.offline.clearCache()
    }
    localStorage.setItem("fizzy-locale", locale)
  } catch {
    // Storage can be unavailable in private/embedded browsers. Request and
